module LIFObuffer(
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);
// Define parameters
parameter STACK_SIZE = 4;
// Declare internal signals
reg [3:0] stack_mem [STACK_SIZE-1:0];
reg [1:0] SP;
// Combinational logic for EMPTY and FULL flags
assign EMPTY = (SP == 2'b00);
assign FULL = (SP == 2'b11);
// Sequential logic for stack operations
always @(posedge Clk or posedge Rst) begin
    if(Rst) begin
        SP <= 2'b11; // Initialize stack pointer to 4 (empty)
        dataOut <= 4'b0000; // Clear dataOut

        // Initialize stack memory to 0
        for(int i = 0; i < STACK_SIZE; i = i + 1) begin
            stack_mem[i] <= 4'b0000;
        end
    end else begin
        if(EN) begin
            if(!FULL && !RW) begin // Write operation
                stack_mem[SP] <= dataIn;
                SP <= SP - 1;
            end else if(!EMPTY && RW) begin // Read operation
                dataOut <= stack_mem[SP];
                stack_mem[SP] <= 4'b0000;
                SP <= SP + 1;
            end
        end
    end
end
endmodule
